import hashlib,json,struct,tempfile,unittest
from pathlib import Path
import polygon_policy,polygon_resolution
U=struct.Struct('<I');P=struct.Struct('<II');T=struct.Struct('<III')
def save(p,fmt,x):p.write_bytes(b''.join(fmt.pack(*v) if isinstance(v,tuple) else fmt.pack(v) for v in x));return {'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
class ResolveTests(unittest.TestCase):
 def setUp(self):
  self.t=tempfile.TemporaryDirectory();self.addCleanup(self.t.cleanup);b=Path(self.t.name);self.inputs={'physical_rows':save(b/'pr',U,[0,3,4]),'physical_runs':save(b/'pv',P,[(2,1),(8,17),(10,1),(10,1)]),'component_rows':save(b/'cr',U,[0,2,2]),'component_runs':save(b/'cv',T,[(2,5,10),(5,8,11)])};self.grid={'width':10,'height':2,'west':-180,'north':90,'step':36};g={'type':'Polygon','coordinates':[[[-105,55],[-40,55],[-40,89],[-105,89],[-105,55]]]};self.file=b/'src.json';self.file.write_text(json.dumps({'type':'FeatureCollection','features':[{'type':'Feature','properties':{'id':'f'},'geometry':g}]}));s={'source_id':'raw','version':'v','sha256':hashlib.sha256(self.file.read_bytes()).hexdigest(),'r2_bucket':'bucket','r2_key':'key','size_bytes':self.file.stat().st_size};asset={**s,'kind':'raw','provenance':{'representation':'provider_original'},'source_uri':'https://example.com','attribution':'attribution','license_name':'license','license_uri':'https://example.com/license','provider':'provider'};self.sources=[{**s,'path':str(self.file)}];f={'feature_id':'f','source_id':'raw','source_version':'v','source_feature_id':'f','geometry_sha256':hashlib.sha256(json.dumps(g,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'evidence':{'selector_property':'id'}};a={'affiliation_id':'a','decision_revision':'r','scope':'land','relationship':'affiliation','method':'component_intersection_v1','entity_id':3,'feature_id':'f','evidence':{'execution_status':'selected_for_research','selector':{'additional_feature_ids':[],'include_witnesses':[],'exclude_witnesses':[]}}};self.snap={'source':'neon-export','schema':'worldatlas-geography-decision-draft-evidence-v1','decision_revision':{'id':'r','status':'draft'},'entity_revision':{'id':'e'},'sources':[s],'source_lineage_assets':[asset],'source_lineage_dependencies':[],'features':[f],'affiliations':[a],'category_bindings':[{'entity_id':3,'code':19,'physical_class':'land'}]};self.policy=polygon_policy.adapt(self.snap,{'a'})
 def runv(self):return polygon_resolution.resolve(self.policy,self.snap,self.sources,self.grid,self.inputs,lambda:None)
 def test_full_source_to_component(self):
  r=self.runv();self.assertEqual(r['claims'][0]['component_ids'],[10]);self.assertEqual(r['claims'][0]['entity_code'],19)
 def test_containment_selects_full_and_traces_partial(self):
  g={'type':'Polygon','coordinates':[[[-105,55],[40,55],[40,89],[-105,89],[-105,55]]]};self.file.write_text(json.dumps({'type':'FeatureCollection','features':[{'type':'Feature','properties':{'id':'f'},'geometry':g}]}));h=hashlib.sha256(self.file.read_bytes()).hexdigest();self.snap['sources'][0]['sha256']=h;self.snap['source_lineage_assets'][0]['sha256']=h;self.sources[0]['sha256']=h;self.snap['sources'][0]['size_bytes']=self.file.stat().st_size;self.snap['source_lineage_assets'][0]['size_bytes']=self.file.stat().st_size;self.sources[0]['size_bytes']=self.file.stat().st_size;self.snap['features'][0]['geometry_sha256']=hashlib.sha256(json.dumps(g,sort_keys=True,separators=(',',':')).encode()).hexdigest();self.snap['affiliations'][0]['method']='component_containment_v1';self.policy=polygon_policy.adapt(self.snap,{'a'});r=self.runv()['claims'][0];self.assertEqual(r['component_ids'],[10]);self.assertEqual(r['containment']['excluded_partial_components'],[{'component_id_evidence_only':11,'inside_cells':1,'whole_cells':3}])
 def test_containment_rejects_witnesses(self):
  a=self.snap['affiliations'][0];a['method']='component_containment_v1';a['evidence']['selector']['include_witnesses']=[{'lon':'0','lat':'0'}]
  with self.assertRaisesRegex(ValueError,'containment requires'):polygon_policy.adapt(self.snap,{'a'})
 def test_anchored_ring_source_to_component(self):
  import mixed_claims
  raw='<osm><node id="1" version="1" visible="true" lon="-105" lat="55"/><node id="2" version="3" visible="true" lon="-40" lat="55"><tag k="name:en" v="ExampleAnchor"/><tag k="amenity" v="ferry_terminal"/></node><node id="3" version="1" visible="true" lon="-40" lat="89"/><node id="4" version="1" visible="true" lon="-105" lat="89"/><way id="10"><nd ref="1"/><nd ref="2"/><nd ref="3"/></way><way id="11"><nd ref="3"/><nd ref="4"/><nd ref="1"/></way><relation id="20" version="4"><member type="way" ref="10" role="outer"/><member type="way" ref="11" role="outer"/><tag k="type" v="multipolygon"/><tag k="place" v="archipelago"/><tag k="name" v="Demo"/></relation></osm>';self.file.write_text(raw);h=hashlib.sha256(self.file.read_bytes()).hexdigest();
  for z in (self.snap['sources'][0],self.snap['source_lineage_assets'][0],self.sources[0]):z['sha256']=h;z['size_bytes']=self.file.stat().st_size
  self.snap['source_lineage_assets'][0]['source_uri']='https://api.openstreetmap.org/api/0.6/relation/20/full';ring=[[-105.0,55.0],[-40.0,55.0],[-40.0,89.0],[-105.0,89.0],[-105.0,55.0]];gh=lambda g:hashlib.sha256(json.dumps(g,sort_keys=True,separators=(',',':')).encode()).hexdigest();anchor={'node_id':'2','node_version':'3','way_id':'10','expected_tags':{'name:en':'ExampleAnchor','amenity':'ferry_terminal'},'geometry_sha256':gh({'type':'Polygon','coordinates':[ring]})};self.snap['features'][0].update(source_feature_id='20',geometry_sha256=gh({'type':'MultiPolygon','coordinates':[[ring]]}),evidence={'source_format':'osm-xml','relation_version':'4','geometry_hash_method':'binary64-sorted-compact-geojson-v1'});a=self.snap['affiliations'][0];a['method']='osm_archipelago_anchored_rings_intersection_v1';a['evidence']['selector']={'additional_feature_ids':[],'include_witnesses':[],'exclude_witnesses':[],'relation_version':'4','extractor_version':'osm-anchored-outer-rings-v1','expected_identity_tags':{'name':'Demo','place':'archipelago'},'anchors':[anchor]};self.policy=polygon_policy.adapt(self.snap,{'a'});result=self.runv();self.assertEqual(result['claims'][0]['component_ids'],[10]);self.assertEqual(result['claims'][0]['source_features'][0]['selected_anchor_traces'][0]['anchor_node_id'],'2');compiled={'revision':'r','entity_revision':'e','affiliation_ids':['a'],'affiliation_entry_links':{'a':['group-entry']}};claims=mixed_claims.combine(compiled,self.snap,[result],{99});self.assertEqual(claims[10][0]['entry_ids'],['group-entry'])
 def test_source_tamper(self):
  self.file.write_text('{}')
  with self.assertRaisesRegex(ValueError,'source pin mismatch'):self.runv()
 def test_stream_tamper(self):
  Path(self.inputs['component_runs']['path']).write_bytes(b'')
  with self.assertRaisesRegex(ValueError,'stream pin mismatch'):self.runv()
if __name__=='__main__':unittest.main()

class ExclusionTraceTests(ResolveTests):
 def test_selected_assertion_is_carried_without_recomputation(self):
  assertion={'kind':'selected_assertion_not_recomputed','proof_sha256':'a'*64};self.policy['decisions'][0]['exclusion_witness_assertion']=assertion
  result=self.runv();self.assertEqual(result['claims'][0]['exclusion_witness_assertion'],assertion)
